import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_triangle_area_normalcase(self):
        self.assertAlmostEqual(triangle_area(5, 3), 7.5)

    def test_triangle_area_zero_side(self):
        self.assertAlmostEqual(triangle_area(0, 3), 0.0)

    def test_triangle_area_zero_height(self):
        self.assertAlmostEqual(triangle_area(5, 0), 0.0)

    def test_triangle_area_negative_side(self):
        self.assertAlmostEqual(triangle_area(-5, 3), 0.0)

    def test_triangle_area_negative_height(self):
        self.assertAlmostEqual(triangle_area(5, -3), 0.0)

    def test_triangle_area_floats(self):
        self.assertAlmostEqual(triangle_area(2.5, 3.5), 5.5)

    def test_triangle_area_float_side(self):
        self.assertAlmostEqual(triangle_area(2.5, 3), 3.75)

    def test_triangle_area_float_height(self):
        self.assertAlmostEqual(triangle_area(5, 3.5), 7.875)

    def test_triangle_area_none(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 3)

    def test_triangle_area_none_height(self):
        with self.assertRaises(TypeError):
            triangle_area(5, None)
